    @Test @org.junit.jupiter.api.condition.EnabledIfSystemProperty(named="browserTest",matches="true")
    void browserProposesAndReviewsPartialServiceWithRealPostgres() throws Exception {
        Fixture f=fixture(); Account responsible=account("assessment-responsible"); Account reviewer=account("assessment-reviewer"); grant(responsible,f.institution);grant(reviewer,f.institution);String responsibleSecret=enroll(responsible);String reviewerSecret=enroll(reviewer);
        UUID assessment=manualAssessment(f,responsible.id);
        ProcessBuilder browser=new ProcessBuilder("npm","run","test","--","tests/service-assessment-real.spec.ts");browser.directory(Path.of("..","web").toFile());browser.redirectErrorStream(true);browser.redirectOutput(Path.of("target","service-assessment-playwright.log").toFile());browser.environment().put("API_TARGET","http://127.0.0.1:"+port);browser.environment().put("VITE_ENABLE_OPERATIONAL_TEST_PANELS","true");browser.environment().put("ASSESSMENT_RESPONSIBLE_EMAIL",responsible.email);browser.environment().put("ASSESSMENT_RESPONSIBLE_MFA_SECRET",responsibleSecret);browser.environment().put("ASSESSMENT_REVIEWER_EMAIL",reviewer.email);browser.environment().put("ASSESSMENT_REVIEWER_MFA_SECRET",reviewerSecret);browser.environment().put("ASSESSMENT_ID",assessment.toString());Process child=browser.start();assertThat(child.waitFor(150,TimeUnit.SECONDS)).isTrue();assertThat(child.exitValue()).isZero();
        assertThat(jdbc.queryForObject("SELECT estado FROM apuracao_remuneracao WHERE id=?",String.class,assessment)).isEqualTo("APROVADA");assertThat(jdbc.queryForObject("SELECT count(*) FROM auditoria_apuracao WHERE apuracao_id=? AND acao='APROVADA'",Long.class,assessment)).isEqualTo(1);assertThat(jdbc.queryForObject("SELECT count(*) FROM operacao_financeira WHERE chave_negocio=?",Long.class,"liquidacao:apuracao:"+assessment)).isEqualTo(1);assertThat(jdbc.queryForObject("SELECT estado FROM operacao_financeira WHERE chave_negocio=?",String.class,"estorno:apuracao:"+assessment)).isEqualTo("PENDENTE");assertThat(jdbc.queryForObject("SELECT count(*) FROM repasse WHERE referencia=?",Long.class,"repasse:apuracao:"+assessment)).isEqualTo(1);assertThat(jdbc.queryForObject("SELECT estado FROM reserva_subsidio WHERE orcamento_id=?",String.class,f.quote)).isEqualTo("ENCERRADA");assertThat(jdbc.queryForObject("SELECT reservado FROM conta_programa WHERE programa_id=?",BigDecimal.class,f.program)).isEqualByComparingTo("0.00");assertThat(jdbc.queryForObject("SELECT count(*) FROM lancamento_financeiro l JOIN operacao_financeira o ON o.id=l.operacao_id WHERE o.chave_negocio=?",Long.class,"liquidacao:apuracao:"+assessment)).isEqualTo(3);
    }

    @Test void manualAssessmentRejectsSelfApprovalMissingMfaAndForeignAccessAndIsIdempotent() throws Exception {
        Fixture f=fixture();Account responsible=account("assessment-self");Account reviewer=account("assessment-other");Account outsider=account("assessment-outsider");grant(responsible,f.institution);grant(reviewer,f.institution);String responsibleSecret=enroll(responsible);String reviewerSecret=enroll(reviewer);responsible=loginAgain(responsible);reviewer=loginAgain(reviewer);UUID assessment=manualAssessment(f,responsible.id);
        Map<String,Object> proposal=Map.of("driverAmount",12.00,"patientAmount",10.00,"institutionAmount",2.00,"reason","Deslocamento comprovado","evidenceReferences",java.util.List.of("evidencia:deslocamento"));
        assertThat(request(responsible,"POST","/financial/assessments/"+assessment+"/proposal",proposal,"proposal-key").statusCode()).isEqualTo(403);
        elevate(responsible,responsibleSecret);assertThat(request(responsible,"POST","/financial/assessments/"+assessment+"/proposal",proposal,"proposal-key").statusCode()).isEqualTo(200);assertThat(request(responsible,"POST","/financial/assessments/"+assessment+"/proposal",proposal,"proposal-key").statusCode()).isEqualTo(200);
        assertThat(request(responsible,"POST","/financial/assessments/"+assessment+"/review",Map.of("decision","APROVAR","reason","Não posso revisar minha proposta"),"self-review").statusCode()).isEqualTo(422);
        assertThat(request(reviewer,"GET","/financial/assessments/"+assessment,null,null).statusCode()).isEqualTo(403);elevate(reviewer,reviewerSecret);assertThat(request(outsider,"GET","/financial/assessments/"+assessment,null,null).statusCode()).isEqualTo(404);
        Map<String,Object> review=Map.of("decision","APROVAR","reason","Revisão independente com evidência suficiente");assertThat(request(reviewer,"POST","/financial/assessments/"+assessment+"/review",review,"review-key").statusCode()).isEqualTo(200);assertThat(request(reviewer,"POST","/financial/assessments/"+assessment+"/review",review,"review-key").statusCode()).isEqualTo(200);assertThat(jdbc.queryForObject("SELECT count(*) FROM operacao_financeira WHERE chave_negocio=?",Long.class,"liquidacao:apuracao:"+assessment)).isEqualTo(1);
    }

    @Test void concurrentReviewCreatesOneObligation() throws Exception {
        Fixture f=fixture();Account rawA=account("assessment-concurrent-a"),rawB=account("assessment-concurrent-b");grant(rawA,f.institution);grant(rawB,f.institution);String as=enroll(rawA),bs=enroll(rawB);Account a=loginAgain(rawA),b=loginAgain(rawB);UUID id=manualAssessment(f,a.id);Map<String,Object> prop=Map.of("driverAmount",8.00,"patientAmount",8.00,"institutionAmount",0.00,"reason","Execução parcial","evidenceReferences",java.util.List.of("evidencia:rota"));elevate(a,as);request(a,"POST","/financial/assessments/"+id+"/proposal",prop,"p");elevate(b,bs);Map<String,Object> review=Map.of("decision","APROVAR","reason","Revisão concorrente");ExecutorService pool=Executors.newFixedThreadPool(2);try{var results=pool.invokeAll(java.util.List.<Callable<HttpResponse<String>>>of(()->request(b,"POST","/financial/assessments/"+id+"/review",review,"r1"),()->request(b,"POST","/financial/assessments/"+id+"/review",review,"r2")));assertThat(results.stream().map(x->{try{return x.get().statusCode();}catch(Exception e){throw new RuntimeException(e);}}).toList()).allMatch(s->s==200||s==409);}finally{pool.shutdownNow();}assertThat(jdbc.queryForObject("SELECT count(*) FROM operacao_financeira WHERE chave_negocio=?",Long.class,"liquidacao:apuracao:"+id)).isEqualTo(1);
    }

    @Test void insufficientCoverageRemainsPendingWithoutFinancialEffect() throws Exception {
        Fixture f=fixture(); Account raw=account("assessment-coverage"); grant(raw,f.institution); String secret=enroll(raw); Account a=loginAgain(raw); UUID id=manualAssessment(f,a.id); elevate(a,secret);
        Map<String,Object> excess=Map.of("driverAmount",26.00,"patientAmount",20.00,"institutionAmount",6.00,"reason","Valor acima da cobertura aceita","evidenceReferences",java.util.List.of("evidencia:cobertura"));
        assertThat(request(a,"POST","/financial/assessments/"+id+"/proposal",excess,"coverage-excess").statusCode()).isEqualTo(422);
        assertThat(jdbc.queryForObject("SELECT estado FROM apuracao_remuneracao WHERE id=?",String.class,id)).isEqualTo("PENDENTE_REVISAO");
        assertThat(jdbc.queryForObject("SELECT valor_liquidado FROM reserva_subsidio WHERE orcamento_id=?",BigDecimal.class,f.quote)).isEqualByComparingTo("0.00");
        assertThat(jdbc.queryForObject("SELECT count(*) FROM operacao_financeira WHERE pedido_id=? AND tipo IN ('LIQUIDACAO','ESTORNO')",Long.class,f.order)).isEqualTo(0);
    }

    private UUID manualAssessment(Fixture f,UUID responsible){UUID id=UUID.randomUUID();UUID incident=UUID.randomUUID();jdbc.update("INSERT INTO ocorrencia_entrega(id,pedido_id,designacao_id,aberta_por,tipo,descricao,estado,decisao,destino_tipo,resolvida_em,encerrada_em) VALUES (?,?,?,?,'OUTRA','Serviço parcial sintético','ENCERRADA','ENCERRAR','UNIDADE',clock_timestamp(),clock_timestamp())",incident,f.order,f.assignment,f.patientUser);jdbc.update("INSERT INTO apuracao_remuneracao(id,pedido_id,designacao_id,orcamento_id,ocorrencia_id,modalidade,estado,moeda,responsavel_id,motivo,evidencias,proposta) VALUES (?,?,?,?,?,'SERVICO_PARCIAL','PENDENTE_REVISAO','BRL',?,?,?::jsonb,'{}'::jsonb)",id,f.order,f.assignment,f.quote,incident,responsible,"Pré-condição sintética","[\"evidencia:ocorrencia\"]");return id;}
    private Fixture fixture(){UUID institution=UUID.randomUUID(),program=UUID.randomUUID(),patientUser=UUID.randomUUID(),patient=UUID.randomUUID(),driverUser=UUID.randomUUID(),driver=UUID.randomUUID(),vehicle=UUID.randomUUID(),link=UUID.randomUUID(),tariff=UUID.randomUUID(),cancel=UUID.randomUUID(),policy=UUID.randomUUID(),order=UUID.randomUUID(),quote=UUID.randomUUID(),assignment=UUID.randomUUID();String pe="patient-"+patientUser+"@example.test",de="driver-"+driverUser+"@example.test",cpf=patient.toString().replace("-","").substring(0,11);insertUser(patientUser,pe,"patient");insertUser(driverUser,de,"driver");jdbc.update("INSERT INTO instituicao(id,nome,estado) VALUES (?,?,'HABILITADA')",institution,"Instituição de teste");jdbc.update("INSERT INTO programa(id,instituicao_id,codigo,nome,estado) VALUES (?,?,?,'Programa de teste','HABILITADO')",program,institution,"P"+program.toString().substring(0,8));jdbc.update("INSERT INTO paciente(id,usuario_id,cpf_cifrado,cpf_busca,nascimento,identidade_estado) VALUES (?,?,?,?,DATE '1980-01-01','VERIFICADA')",patient,patientUser,protector.encrypt(cpf),protector.lookup(cpf));jdbc.update("INSERT INTO entregador(id,usuario_id,nascimento,estado) VALUES (?,?,DATE '1990-01-01','APROVADO')",driver,driverUser);jdbc.update("INSERT INTO veiculo(id,placa,marca,modelo,cor,ano_fabricacao,ano_modelo,estado) VALUES (?,?,'M','M','A',2024,2024,'APROVADO')",vehicle,"P"+vehicle.toString().substring(0,7));jdbc.update("INSERT INTO vinculo_veiculo(id,entregador_id,veiculo_id,tipo,estado,valido_ate,version) VALUES (?,?,?,'PROPRIEDADE','APROVADO',current_date+10,1)",link,driver,vehicle);jdbc.update("INSERT INTO tarifa(id,numero,formula_codigo,parametros,inicio,estado) VALUES (?,(SELECT coalesce(max(numero),0)+1 FROM tarifa),'BASE_KM_MINUTO','{}',clock_timestamp(),'ATIVA')",tariff);jdbc.update("INSERT INTO politica_cancelamento(id,numero,criterios,inicio,estado) VALUES (?,(SELECT coalesce(max(numero),0)+1 FROM politica_cancelamento),'{}',clock_timestamp(),'ATIVA')",cancel);jdbc.update("INSERT INTO politica_designacao(id,numero,limite_tarefas_simultaneas,inicio,estado) VALUES (?,(SELECT coalesce(max(numero),0)+1 FROM politica_designacao),1,clock_timestamp(),'ATIVA')",policy);byte[] data=protector.encrypt("fixture");jdbc.update("INSERT INTO pedido(id,paciente_id,solicitante_id,origem_cifrada,destino_cifrada,origem_lat,origem_lon,destino_lat,destino_lon,destinatario_id,unidade_id,estado,version) VALUES (?,?,?,?,?,-23,-46,-23,-46,?,?,'OCORRENCIA',1)",order,patient,patientUser,data,data,patientUser,UUID.randomUUID());jdbc.update("INSERT INTO orcamento(id,pedido_id,paciente_id,tarifa_id,rota_provedor,rota_referencia,distancia_m,duracao_s,rota_calculada_em,transito_incluido,politica_snapshot,frete,paciente_valor,subsidio_valor,moeda,expira_em,aceito_em,estado,programa_id,politica_cancelamento_id,pedido_version) VALUES (?,?,?,?,'test','route',1000,600,clock_timestamp(),false,'{}',25,20,5,'BRL',clock_timestamp()+interval '1 hour',clock_timestamp(),'ACEITO',?,?,1)",quote,order,patient,tariff,program,cancel);jdbc.update("INSERT INTO conta_programa(programa_id,disponivel,reservado,moeda) VALUES (?,0,5,'BRL')",program);jdbc.update("INSERT INTO reserva_subsidio(id,orcamento_id,pedido_id,programa_id,paciente_id,valor,moeda,estado) VALUES (?,?,?,?,?,5,'BRL','RESERVADA')",UUID.randomUUID(),quote,order,program,patient);jdbc.update("INSERT INTO operacao_financeira(id,pedido_id,tipo,chave_negocio,valor,moeda,estado) VALUES (?,?,'COBRANCA',?,20,'BRL','CONFIRMADA')",UUID.randomUUID(),order,"cobranca:"+order);jdbc.update("INSERT INTO designacao(id,pedido_id,entregador_id,vinculo_id,orcamento_id,politica_designacao_id,politica_cancelamento_id,pedido_version,limite_tarefas_snapshot,identificacao_snapshot) VALUES (?,?,?,?,?,?,?,1,1,'{}')",assignment,order,driver,link,quote,policy,cancel);return new Fixture(institution,program,patientUser,order,quote,assignment);}
    private void insertUser(UUID id,String email,String name){jdbc.update("INSERT INTO usuario(id,email_cifrado,email_busca,senha_hash,nome_cifrado,estado,email_verificado_em) VALUES (?,?,?,?,?,'ATIVO',clock_timestamp())",id,protector.encrypt(email),protector.lookup(email),Passwords.hash(password),protector.encrypt(name));}
    private Account account(String prefix)throws Exception{UUID id=UUID.randomUUID();String email=prefix+id+"@example.test";insertUser(id,email,prefix);var r=requestRaw(null,"POST","/auth/login",Map.of("email",email,"password",password,"client","MOBILE"),null);return new Account(id,email,json.readTree(r.body()).get("accessToken").asText());}
    private Account loginAgain(Account a)throws Exception{var r=requestRaw(null,"POST","/auth/login",Map.of("email",a.email,"password",password,"client","MOBILE"),null);return new Account(a.id,a.email,json.readTree(r.body()).get("accessToken").asText());}
    private void grant(Account a,UUID institution){jdbc.update("INSERT INTO papel_global(usuario_id,papel) VALUES (?,'GESTOR_FINANCEIRO') ON CONFLICT DO NOTHING",a.id);jdbc.update("INSERT INTO membro_instituicao(instituicao_id,usuario_id,papel) VALUES (?,?,'GESTOR_FINANCEIRO')",institution,a.id);}
    private String enroll(Account a)throws Exception{var r=request(a,"POST","/me/mfa/totp/enrollment",Map.of("password",password),null);String secret=json.readTree(r.body()).get("secret").asText();long step=Instant.now().getEpochSecond()/30;assertThat(request(a,"POST","/me/mfa/totp/confirmation",Map.of("code",MfaService.totp(MfaService.decodeBase32(secret),step)),null).statusCode()).isEqualTo(200);return secret;}
    private void elevate(Account a,String secret)throws Exception{long step=Instant.now().getEpochSecond()/30+1;assertThat(request(a,"POST","/me/mfa/verification",Map.of("code",MfaService.totp(MfaService.decodeBase32(secret),step)),null).statusCode()).isEqualTo(200);}
    private HttpResponse<String> request(Account a,String method,String path,Object value,String key)throws Exception{return requestRaw(a,method,path,value,key);}
    private HttpResponse<String> requestRaw(Account a,String method,String path,Object value,String key)throws Exception{var b=HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+"/api/v1"+path)).header("Content-Type","application/json");if(a!=null)b.header("Authorization","Bearer "+a.token);if(key!=null)b.header("Idempotency-Key",key);String body=value==null?null:json.writeValueAsString(value);return http.send(b.method(method,body==null?HttpRequest.BodyPublishers.noBody():HttpRequest.BodyPublishers.ofString(body)).build(),HttpResponse.BodyHandlers.ofString());}
    record Account(UUID id,String email,String token){} record Fixture(UUID institution,UUID program,UUID patientUser,UUID order,UUID quote,UUID assignment){}
